example:
consumes bynk { Clock }

store live: Cache[String, Int] @ttl(5.minutes)

on call touch() -> Effect[()] {
    let _ <- live.put("a", 1)   // ✗ expiry reads the clock, which the handler does not declare
    Effect.pure(())
}

on call touch() -> Effect[()] given Clock {   // ✓ declare the clock
    let _ <- live.put("a", 1)
    Effect.pure(())
}
